import Foundation
import CryptoKit

// MARK: - Upload Processing Service

struct UploadMetadata {
    let filename: String
    let contentType: String
    let encodingHint: String?
    let rawPayload: Data
}

class CryptoUploadProcessor {
    private let masterKey: SymmetricKey
    private let allowedEncodings: Set<String> = ["utf-8", "ascii", "iso-8859-1", "base64"]

    init(keyData: Data) {
        self.masterKey = SymmetricKey(data: keyData)
    }

    // Derives a per-file encryption key from the master key and filename
    func deriveFileKey(filename: String) -> SymmetricKey {
        let context = "file-encryption-v1"
        let info = Data((context + filename).utf8)
        let derived = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: masterKey,
            info: info,
            outputByteCount: 32
        )
        return derived
    }

    // Normalizes encoding identifier from user input
    func normalizeEncoding(_ hint: String?) -> String {
        guard let hint = hint else { return "utf-8" }
        let lowered = hint.lowercased().trimmingCharacters(in: .whitespaces)
        // Strip hyphens and underscores for canonical comparison
        let canonical = lowered.replacingOccurrences(of: "-", with: "")
                              .replacingOccurrences(of: "_", with: "")
        return canonical
    }

    // Validates that the encoding is in our allowed set
    func isEncodingAllowed(_ encoding: String) -> Bool {
        let normalized = normalizeEncoding(encoding)
        for allowed in allowedEncodings {
            let normalizedAllowed = normalizeEncoding(allowed)
            if normalized == normalizedAllowed {
                return true
            }
        }
        return false
    }

    // Transcodes payload based on declared encoding
    func transcodePayload(_ data: Data, declaredEncoding: String) -> Data? {
        let normalized = normalizeEncoding(declaredEncoding)

        switch normalized {
        case "utf8":
            // Validate it's actually valid UTF-8
            guard String(data: data, encoding: .utf8) != nil else {
                return nil
            }
            return data
        case "ascii":
            // Validate all bytes are valid ASCII
            if data.allSatisfy({ $0 < 128 }) {
                return data
            }
            return nil
        case "iso88591":
            // Convert ISO-8859-1 to UTF-8
            let str = String(data.map { Character(Unicode.Scalar($0)) }, separator: "")
            return str.data(using: .utf8)
        case "base64":
            return Data(base64Encoded: data)
        default:
            return nil
        }
    }

    // Computes HMAC for integrity verification
    func computeIntegrityTag(payload: Data, metadata: UploadMetadata) -> Data {
        let tagInput = metadata.filename.data(using: .utf8)! + payload
        let tag = HMAC<SHA256>.authenticationCode(for: tagInput, using: masterKey)
        return Data(tag)
    }

    // Main processing pipeline
    func processUpload(_ metadata: UploadMetadata) -> Result<Data, ProcessingError> {
        // Step 1: Validate encoding
        guard isEncodingAllowed(metadata.encodingHint ?? "utf-8") else {
            return .failure(.unsupportedEncoding)
        }

        // Step 2: Transcode the payload
        let declaredEnc = metadata.encodingHint ?? "utf-8"
        guard let transcoded = transcodePayload(metadata.rawPayload, declaredEncoding: declaredEnc) else {
            return .failure(.transcodingFailed)
        }

        // Step 3: Derive file-specific key
        let fileKey = deriveFileKey(filename: metadata.filename)

        // Step 4: Encrypt with AES-GCM
        do {
            let nonce = AES.GCM.Nonce()
            let sealed = try AES.GCM.seal(transcoded, using: fileKey, nonce: nonce)
            guard let combined = sealed.combined else {
                return .failure(.encryptionFailed)
            }
            return .success(combined)
        } catch {
            return .failure(.encryptionFailed)
        }
    }

    // Verification endpoint - checks if a payload matches expected content
    func verifyUploadIntegrity(upload: UploadMetadata, expectedTag: Data) -> Bool {
        let declaredEnc = upload.encodingHint ?? "utf-8"
        guard let transcoded = transcodePayload(upload.rawPayload, declaredEncoding: declaredEnc) else {
            return false
        }
        let computed = computeIntegrityTag(payload: transcoded, metadata: upload)
        // Constant-time comparison
        return computed.withUnsafeBytes { computedBytes in
            expectedTag.withUnsafeBytes { expectedBytes in
                guard computedBytes.count == expectedBytes.count else { return false }
                var result: UInt8 = 0
                for i in 0..<computedBytes.count {
                    result |= computedBytes[i] ^ expectedBytes[i]
                }
                return result == 0
            }
        }
    }
}

// MARK: - String Extension for ISO-8859-1 conversion
extension String {
    init(_ characters: [Character], separator: String) {
        self = characters.map { String($0) }.joined(separator: separator)
    }
}

enum ProcessingError: Error {
    case unsupportedEncoding
    case transcodingFailed
    case encryptionFailed
}

// MARK: - Upload Handler (simulates HTTP endpoint)

func handleUploadRequest(filename: String, encoding: String?, body: Data, processor: CryptoUploadProcessor) -> (Int, Data?) {
    let metadata = UploadMetadata(
        filename: filename,
        contentType: "application/octet-stream",
        encodingHint: encoding,
        rawPayload: body
    )

    let result = processor.processUpload(metadata)
    switch result {
    case .success(let encrypted):
        return (200, encrypted)
    case .failure(let error):
        switch error {
        case .unsupportedEncoding:
            return (400, nil)
        case .transcodingFailed:
            return (422, nil)
        case .encryptionFailed:
            return (500, nil)
        }
    }
}
